#include <iostream>
#include <cstring>
#include <algorithm>
#include <vector>
using namespace std;

using ll = long long;

const ll MOD1 = 998244353;
const ll MOD2 = 1000000007;

ll N;
vector<int> digits;
int temp[15];
int result = 0;

ll buildNumber(const vector<int>& arr, int len) {
    ll val = 0;
    for (int i = 0; i < len; ++i)
        val = val * 10 + arr[i];
    return val;
}

ll computeRank(const vector<int>& arr, int len) {
    ll cnt = 0;
    for (int d = 1; d <= (int)digits.size(); ++d) {
        for (int i = 0; i < min(len, d); ++i) {
            int start = (i == 0) ? 1 : 0;
            for (int digit = start; digit < arr[i]; ++digit) {
                ll low = 0, high = 0;
                for (int p = 0; p < i; ++p)
                    low = high = low * 10 + arr[p];
                low = high = low * 10 + digit;
                for (int p = i + 1; p < d; ++p)
                    low *= 10, high = high * 10 + 9;
                high = min(high, N);
                if (low <= high)
                    cnt += high - low + 1;
            }
        }
        if (d <= len) ++cnt;
    }
    return cnt;
}

ll evaluate(const vector<int>& arr, int len) {
    return ((-buildNumber(arr, len) + computeRank(arr, len)) % MOD1 + MOD1) % MOD1;
}

int diff[15];
vector<int> queue1, queue2;
ll sumQueue2 = 0;

void generate(int pos, int end, vector<int>& q, ll val) {
    if (pos == end) {
        for (int d = 0; d <= 9; ++d)
            q.push_back((val + 1LL * d * diff[pos]) % MOD1);
        return;
    }
    for (int d = 0; d <= 9; ++d)
        generate(pos + 1, end, q, (val + 1LL * d * diff[pos]) % MOD1);
}

void applyUpdate(int len, int idx, int val) {
    temp[0] = digits.size();
    for (int i = 0; i < (int)digits.size(); ++i)
        temp[i + 1] = digits[i];
    temp[idx + 1] = val;
    for (int p = idx + 2; p <= len; ++p)
        temp[p] = 0;
    vector<int> arr(temp + 1, temp + len + 1);
    ll baseVal = evaluate(arr, len);
    for (int p = idx + 2; p <= len; ++p) {
        temp[p] = 1;
        vector<int> arr2(temp + 1, temp + len + 1);
        diff[p] = (evaluate(arr2, len) + MOD1 - baseVal) % MOD1;
        temp[p] = 0;
    }
    if (len - idx == 0) {
        result = (result + baseVal) % MOD2;
        return;
    }
    if (len - idx == 1) {
        for (int d = 0; d <= 9; ++d)
            result = (result + (baseVal + 1LL * d * diff[len]) % MOD1) % MOD2;
        return;
    }
    int mid = (len + idx) / 2;
    queue1.clear(); queue2.clear();
    generate(idx + 1, mid, queue1, baseVal);
    generate(mid + 1, len, queue2, 0);
    sort(queue2.begin(), queue2.end());
    sumQueue2 = 0;
    for (int x : queue2)
        sumQueue2 = (sumQueue2 + x) % MOD2;
    for (int x : queue1) {
        int pos = lower_bound(queue2.begin(), queue2.end(), MOD1 - x) - queue2.begin();
        result = (result + sumQueue2 + 1LL * queue2.size() * x) % MOD2;
        result = (result + 1LL * (queue2.size() - pos) * (MOD2 - MOD1)) % MOD2;
    }
}

int main() {
    cin >> N;
    while (N) {
        digits.push_back(N % 10);
        N /= 10;
    }
    reverse(digits.begin(), digits.end());
    N = 0;
    for (int i = 0; i < (int)digits.size(); ++i)
        N = N * 10 + digits[i];
    for (int len = 1; len <= (int)digits.size(); ++len) {
        for (int pos = 0; pos < len; ++pos) {
            int low = (pos == 0) ? 1 : 0;
            int high = (len == (int)digits.size()) ? digits[pos] - 1 : 9;
            for (int d = low; d <= high; ++d) {
                if (d != digits[pos])
                    applyUpdate(len, pos, d);
            }
        }
        vector<int> arr(digits.begin(), digits.begin() + len);
        result = (result + evaluate(arr, len)) % MOD2;
    }
    cout << result << endl;
}
